with metrics as (select id, account_id, txn_type, amount, txn_time, merchant, is_flagged, percent_rank() over (order by amount) as amount_percent_rank, lead(amount, 2) over (partition by account_id order by amount, id) as next_amount, sum(amount) over (order by cast(txn_time as bigint) range between 2592000 preceding and current row) as amount_sum_30d, max(amount) over (partition by merchant, account_id order by cast(txn_time as bigint) range between 2592000 preceding and current row) as amount_max_30d, avg(amount) over (partition by merchant, account_id order by amount, id rows between 6 preceding and current row) as amount_avg_6 from transactions) select account_id, max(txn_time) as ended_at, max(txn_time) as last_seen, count_if(merchant = '7-Eleven') as 7_eleven_events, min(amount_avg_6) as min_amount_avg_6, count_if(merchant = 'Starbucks') as starbucks_events from metrics group by account_id order by starbucks_events;
